SELECT
FROM shop_delivery_company c
c.is_deleted = 0
AND (c.company_name LIKE CONCAT('%', #{q.keyword}, '%') OR c.company_code LIKE CONCAT('%', #{q.keyword}, '%') OR c.company_short LIKE CONCAT('%', #{q.keyword}, '%'))
AND c.company_type = #{q.companyType}
AND c.status = #{q.status}
AND (
OR c.support_cod = 1 OR c.support_insurance = 1 OR c.support_fragile = 1
)
ORDER BY c.status DESC, c.sort ASC, c.id DESC
